const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const body = ($('Приём документа').item.json.body) || {};
let mime = body.mime_type || ($input.item.binary && $input.item.binary.data && $input.item.binary.data.mimeType) || 'image/jpeg';
return { json: { file_base64: base64, file_mime: mime, doc_id: body.doc_id || null } };

const doc = ($('Приём документа').item.json.body) || {};
const resp = $json;
let text = '';
try { text = resp.candidates[0].content.parts[0].text; } catch (e) {}
let arr = [];
try { const p = JSON.parse(text); arr = Array.isArray(p) ? p : (p.positions || p.items || []); } catch (e) { arr = []; }
const positions = arr.map((x, i) => ({
  id: (doc.doc_id || 'doc') + '-' + (i + 1),
  name: x.name || null,
  amount: (x.amount != null ? x.amount : null),
  vat: (x.vat != null ? x.vat : null),
  doc_number: x.doc_number || null,
  doc_date: x.doc_date || null,
  supplier: x.supplier || null
}));
return { json: { doc_id: doc.doc_id || null, positions: positions, count: positions.length, model: 'gemini-2.5-flash' } };
